CREATE TABLE IF NOT EXISTS admin_user(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(32) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,token_version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS category(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(40) NOT NULL UNIQUE,slug VARCHAR(60) NOT NULL UNIQUE,description VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS tag(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(30) NOT NULL UNIQUE,slug VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS article(
 id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,excerpt VARCHAR(400) NOT NULL,body LONGTEXT NOT NULL,
 cover VARCHAR(500) NOT NULL,category_id BIGINT NOT NULL,status VARCHAR(16) NOT NULL,featured BOOLEAN NOT NULL DEFAULT FALSE,
 version INT NOT NULL DEFAULT 0,published_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,
 FOREIGN KEY(category_id) REFERENCES category(id),INDEX idx_article_public(status,published_at),INDEX idx_article_category(category_id,status)
);
CREATE TABLE IF NOT EXISTS article_tag(article_id BIGINT NOT NULL,tag_id BIGINT NOT NULL,PRIMARY KEY(article_id,tag_id),FOREIGN KEY(article_id) REFERENCES article(id),FOREIGN KEY(tag_id) REFERENCES tag(id));
CREATE TABLE IF NOT EXISTS guest_message(id BIGINT PRIMARY KEY AUTO_INCREMENT,nickname VARCHAR(30) NOT NULL,content VARCHAR(800) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP NOT NULL,INDEX idx_message_status(status,created_at));
CREATE TABLE IF NOT EXISTS friend_link(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(60) NOT NULL,url VARCHAR(300) NOT NULL,description VARCHAR(200) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS site_config(id INT PRIMARY KEY,content LONGTEXT NOT NULL);
